/** 生成ファイル冒頭のマーカー。CLI はこのマーカーを持つファイルだけを削除・上書きする。 */
export const GENERATED_MARKER = "<auto-generated />";

export function tsHeader(): string {
  return [
    `// ${GENERATED_MARKER}`,
    "// このファイルは `pnpm gen` により contract/contract.schema.json から生成されました。",
    "// DO NOT EDIT — 手で編集しないでください。再生成で上書きされます。",
    "",
  ].join("\n");
}

export function vbHeader(): string {
  return [
    `' ${GENERATED_MARKER}`,
    "' このファイルは `pnpm gen` により contract/contract.schema.json から生成されました。",
    "' DO NOT EDIT — 手で編集しないでください。再生成で上書きされます。",
    "Option Strict On",
    "Option Explicit On",
    "Option Infer On",
    "",
  ].join("\n");
}
